import os
from .counters_checker import CounterVerifier, parse_counters_with_names
from .logger import table_counter_logger
from .evaluators import CountersEvaluator
from .counters_fetchers import FileCountersFetcher
from robot.api import logger
from robot.libraries.BuiltIn import BuiltIn
from robot.errors import ExecutionFailed


class counters_checker(object):
    @staticmethod
    def verify_last_counters_in_file(*args, **kwargs):
        """
        You can use this keyword for check a lot of counters in one file.
        This keyword looks on last occurrence counter in file.
        After the execution of the keyword, you will find the results in the table with the individual counters in log.html

        :param *args: couter_id, expectations, name for each counter
        :param string local_moid: localMOid from PM file, ie. DN:NE-LNBTS-1/LNCEL-1/MCC-244/MNC-09
        :param string file_path: unpacked file location (xml) with counters values

        Example:

        ::

            ${COUNTER_FILE}=    Get Latest Unpacked Raw Pm Counters File
            Verify Last Counters In File
            ...    M55139C00010    0    SGNB_SA_DU_RAC_REJ_DUE_PUCCH
            ...    M55139C00013    >0    SGNB_SA_DU_RAC_REJ_DUE_RRC
            ...    M55139C00014    <0    SGNB_SA_DU_RAC_REJ_DUE_NGBR
            ...    M55138C00006    \=0    SGNB_SA_RAC_REJ_DUE_TO_RRC
            ...    M55138C00002    !\=0    SGNB_SA_ADMISSION_SUCC
            ...    local_moid=PLMN-PLMN/MRBTS-2003/NRBTS-2003/NRCELL-1
            ...    file_path=${COUNTER_FILE}
        """  # noqa: W605
        local_moid = kwargs.pop('local_moid', 'DN:NE-LNBTS-1/LNCEL-1/MCC-244/MNC-09')
        file_path = kwargs.pop('file_path', None)
        verifier_instance = CounterVerifier(
            parse_counters_with_names,
            FileCountersFetcher(file_path, local_moid),
            CountersEvaluator(),
            table_counter_logger,
        )
        verifier_instance.parse_expectations(args)
        verifier_instance.get_last_counters_values()
        verifier_instance.verify_counters_values()
        verifier_instance.log_verification_results()
        verifier_instance.apply_verdict()

    @staticmethod
    def verify_any_counters_in_file(*args, **kwargs):
        """
        Like *verify_last_counters_in_file* but, this keyword checks at least one counter is validated.

        Additionally, available is the '+' operator, which checks if the sum is equal to the given value.

        :param report_pm_counter: by default set to False
        :note: PM counters are not reported immediately.
        PM counters will be read by ute_reporting_portal script and will be added to robot report.

        Example:

        ::

            Verify Any Counters In File
            ...    M55139C00010    +5    SGNB_SA_DU_RAC_REJ_DUE_PUCCH
            ...    local_moid=PLMN-PLMN/MRBTS-2003/NRBTS-2003/NRCELL-1
            ...    file_path=${COUNTER_FILE}

        """
        report_pm_counter = kwargs.pop('report_pm_counter', False)
        local_moid = kwargs.pop('local_moid', 'DN:NE-LNBTS-1/LNCEL-1/MCC-244/MNC-09')
        file_path = kwargs.pop('file_path', None)
        verifier_instance = CounterVerifier(
            parse_counters_with_names,
            FileCountersFetcher(file_path, local_moid),
            CountersEvaluator(),
            table_counter_logger,
        )
        verifier_instance.parse_expectations(args)
        verifier_instance.get_all_counters_values()
        verifier_instance.verify_counters_values()
        if report_pm_counter:
            results = verifier_instance.counters_data
            logger.console("Report Pm Counter is activated")
            for counter in results:
                counter_id = counter['counter_id']
                try:
                    counter_value = sum(counter['value'])
                except Exception:
                    counter_value = 0
                verification_result = 'Passed' if counter['result'] else 'Failed'
                BuiltIn().run_keyword("report pm counter", counter_id, counter_value, verification_result)
        verifier_instance.log_verification_results()
        verifier_instance.apply_verdict()

    @staticmethod
    def verify_any_counters_in_all_files(*args, **kwargs):  # noqa: C901
        """
        Like *verify_last_counters_in_file* but, this keyword checks at least one counter is validated.
        This keyword checks the counters in every generated PM file.

        Additionally, available is the '+' operator, which checks if the sum is equal to the given value.

        :param report_pm_counter: by default set to False
        :note: PM counters are not reported immediately.
        PM counters will be read by ute_reporting_portal script and will be added to robot report.

        Example:

        ::

            Verify Any Counters In All Files
            ...    M55139C00010    +5    SGNB_SA_DU_RAC_REJ_DUE_PUCCH
            ...    local_moid=PLMN-PLMN/MRBTS-2003/NRBTS-2003/NRCELL-1
            ...    files_path=${COUNTER_FILE}

        """
        report_pm_counter = kwargs.pop('report_pm_counter', False)
        local_moid = kwargs.pop('local_moid', 'DN:NE-LNBTS-1/LNCEL-1/MCC-244/MNC-09')
        files_path = kwargs.pop('files_path', None)
        files_path_list = os.listdir(files_path)

        # Dictionary to track results for each counter
        counters_results = {}

        for i in files_path_list:
            filepath = os.path.join(files_path, i)
            verifier_instance = CounterVerifier(
                parse_counters_with_names,
                FileCountersFetcher(filepath, local_moid),
                CountersEvaluator(),
                table_counter_logger,
            )
            verifier_instance.parse_expectations(args)
            verifier_instance.get_all_counters_values()
            verifier_instance.verify_counters_values()

            # Update results for each counter
            for counter in verifier_instance.counters_data:
                counter_id = counter['counter_id']
                if counter_id not in counters_results:
                    # Initialize the result as False if the counter is missing
                    counters_results[counter_id] = counter['result'] if counter['value'] else False
                else:
                    # Combine results across files (logical OR)
                    counters_results[counter_id] = counters_results[counter_id] or (
                        counter['result'] if counter['value'] else False)

            if report_pm_counter:
                results = verifier_instance.counters_data
                passed_counters = [counter for counter in results if
                                   counter['result'] and counter['value']]  # Filter passed counters with valid values

                if passed_counters:  # Check if there are any passed counters
                    logger.console("Report Pm Counter is activated for passed counters")
                    for counter in passed_counters:
                        counter_id = counter['counter_id']
                        try:
                            counter_value = sum(counter['value'])
                        except Exception:
                            counter_value = 0
                        verification_result = 'Passed' if counter['result'] else 'Failed'
                        BuiltIn().run_keyword("report pm counter", counter_id, counter_value, verification_result)
                else:
                    logger.console("No counters passed, skipping report pm counter")
            verifier_instance.log_verification_results()

        # Check if all provided counters passed
        all_counters_passed = all(counters_results.values())

        if not all_counters_passed:
            failed_counters = [key for key, value in counters_results.items() if not value]
            raise ExecutionFailed(
                message=f"The following counters failed: {', '.join(failed_counters)}",  # noqa: E999
                continue_on_failure=True,
            )

        # Create a new verifier instance for aggregated results
        aggregated_verifier = CounterVerifier(
            parse_counters_with_names,
            None,  # No need for a values fetcher here
            CountersEvaluator(),
            table_counter_logger,
        )
        aggregated_verifier.counters_data = [
            {"counter_id": key, "result": value} for key, value in counters_results.items()
        ]
        aggregated_verifier.pass_flag = all_counters_passed

        # Apply verdict based on aggregated results
        aggregated_verifier.apply_verdict()
